package com.vandorlabs.neoforge.reservoir;
import com.vandorlabs.neoforge.NativeConfigurationAccess;
import net.minecraft.core.registries.Registries;import net.minecraft.resources.ResourceLocation;import net.minecraft.world.level.block.*;import net.minecraft.world.level.block.state.BlockBehaviour;import net.minecraft.world.level.block.entity.BlockEntityType;import net.minecraft.world.inventory.MenuType;import net.minecraft.world.item.*;import net.minecraft.world.entity.player.Player;import net.minecraft.world.level.Level;import net.minecraft.core.BlockPos;import net.minecraft.server.level.ServerPlayer;import net.minecraft.world.SimpleMenuProvider;import net.neoforged.bus.api.SubscribeEvent;import net.neoforged.fml.common.EventBusSubscriber;import net.neoforged.neoforge.registries.RegisterEvent;import net.neoforged.neoforge.capabilities.*;
/** Own storage prerequisite for the native ports; canonical block and tile identities match Source. */
@EventBusSubscriber(modid="vandorlabs",bus=EventBusSubscriber.Bus.MOD)
public final class NativeBufferBindings {
 public static NativeBufferBlock BATTERY,TANK;public static BlockEntityType<NativeBatteryEntity> BATTERY_ENTITY;public static BlockEntityType<NativeHexTankEntity> TANK_ENTITY;public static MenuType<NativeBufferMenu> MENU;
 public static boolean enabled(){return com.vandorlabs.neoforge.ports.NativePortBindings.enabled();}private static ResourceLocation id(String s){return ResourceLocation.fromNamespaceAndPath("vandorlabs",s);}
 @SubscribeEvent public static void register(RegisterEvent e){if(!enabled())return;e.register(Registries.BLOCK,h->{BATTERY=new NativeBufferBlock(true,BlockBehaviour.Properties.of().strength(5,6).requiresCorrectToolForDrops().sound(SoundType.METAL).noOcclusion());TANK=new NativeBufferBlock(false,BlockBehaviour.Properties.of().strength(5,6).requiresCorrectToolForDrops().sound(SoundType.METAL).noOcclusion());h.register(id("battery_block"),BATTERY);h.register(id("hexagonal_fuel_tank"),TANK);});e.register(Registries.ITEM,h->{h.register(id("battery_block"),new NativeBufferItem(BATTERY,new Item.Properties()));h.register(id("hexagonal_fuel_tank"),new NativeBufferItem(TANK,new Item.Properties()));});e.register(Registries.BLOCK_ENTITY_TYPE,h->{BATTERY_ENTITY=BlockEntityType.Builder.of(NativeBatteryEntity::new,BATTERY).build(null);TANK_ENTITY=BlockEntityType.Builder.of(NativeHexTankEntity::new,TANK).build(null);h.register(id("battery"),BATTERY_ENTITY);h.register(id("hex_tank"),TANK_ENTITY);});e.register(Registries.MENU,h->{MENU=net.neoforged.neoforge.common.extensions.IMenuTypeExtension.create((window,inventory,buffer)->new NativeBufferMenu(window,inventory,buffer.readBlockPos()));h.register(id("buffer_status"),MENU);});}
 @SubscribeEvent public static void capabilities(RegisterCapabilitiesEvent e){if(!enabled()||BATTERY_ENTITY==null)return;e.registerBlockEntity(Capabilities.EnergyStorage.BLOCK,BATTERY_ENTITY,(owner,side)->owner.inert()?null:owner.energy(side));e.registerBlockEntity(Capabilities.FluidHandler.BLOCK,TANK_ENTITY,(owner,side)->owner.inert()?null:owner.fluid(side));}
 @SubscribeEvent public static void payloads(net.neoforged.neoforge.network.event.RegisterPayloadHandlersEvent e){NativeBufferSettingsPayload.register(e);BufferTransmissionPayload.register(e);}
 @SubscribeEvent public static void creative(net.neoforged.neoforge.event.BuildCreativeModeTabContentsEvent e){if(enabled()&&e.getTabKey().location().equals(id("vandorlabs"))){e.accept(BATTERY);e.accept(TANK);}}
 public static boolean open(Player player,Level level,BlockPos pos){if(!enabled()||MENU==null||!(level.getBlockEntity(pos) instanceof NativeBufferEntity owner)||owner.inert()||!NativeConfigurationAccess.canEditDialog(player,owner))return false;if(owner instanceof NativeBatteryEntity)return com.vandorlabs.neoforge.ports.NativePortBindings.open(player,level,pos);if(player instanceof ServerPlayer actor){if(!actor.getServer().isSameThread())return false;actor.openMenu(new SimpleMenuProvider((window,inventory,ignored)->new NativeBufferMenu(window,owner),owner.getBlockState().getBlock().getName()),buffer->buffer.writeBlockPos(pos));}return true;}
 private NativeBufferBindings(){}
}
